<?php
namespace App\Http\Controllers;
use App\Actions\Approvals\RequestActionApproval;use App\Enums\ApprovalType;use App\Models\DigitalTransaction;use App\Models\Expense;use App\Models\ExpenseCategory;use App\Models\Refund;use App\Models\Sale;use App\Models\ServiceOrder;use App\Models\TopupOrder;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Carbon;
class StaffFinanceApiController extends Controller{
public function expenses(Request $request):JsonResponse{$this->authorizeFinance($request);$items=Expense::query()->with(['category:id,name','user:id,name'])->latest('expense_date')->paginate(20)->withQueryString();return response()->json(['data'=>['expenses'=>collect($items->items())->map(fn(Expense $e)=>['id'=>$e->id,'expense_number'=>$e->expense_number,'expense_date'=>$e->expense_date?->toDateString(),'category'=>$e->category?->name,'description'=>$e->description,'amount'=>$e->amount,'payment_method'=>$e->payment_method,'requester'=>$e->user?->name])->values(),'categories'=>ExpenseCategory::query()->orderBy('name')->get(['id','name']),'pagination'=>['current_page'=>$items->currentPage(),'last_page'=>$items->lastPage(),'total'=>$items->total()]]]);}
public function requestExpense(Request $request):JsonResponse{$this->authorizeFinance($request);$data=$request->validate(['expense_category_id'=>['required','exists:expense_categories,id'],'amount'=>['required','integer','min:1'],'description'=>['required','string','max:1000'],'expense_date'=>['required','date'],'payment_method'=>['required','in:cash,transfer,qris,ewallet']]);$approval=$this->requestApproval->handle($request->user(),ApprovalType::FinancialExpense,null,['data'=>$data],$data['description']);return response()->json(['message'=>"Pengeluaran menunggu persetujuan ({$approval->request_number}).",'approval'=>['id'=>$approval->id,'request_number'=>$approval->request_number]],202);}
public function daily(Request $request):JsonResponse{$this->authorizeFinance($request);$validated=$request->validate(['date'=>['nullable','date_format:Y-m-d']]);$date=isset($validated['date'])?Carbon::createFromFormat('Y-m-d',$validated['date'])->startOfDay():today();$sales=Sale::query()->whereIn('status',['completed','partially_refunded','refunded'])->whereDate('completed_at',$date)->with(['items','user:id,name'])->get();$expenses=Expense::query()->whereDate('expense_date',$date)->with('category:id,name')->get();$digital=DigitalTransaction::query()->where('status','berhasil')->whereDate('created_at',$date)->get();$topups=TopupOrder::query()->where('payment_status','paid')->where('fulfillment_status','success')->whereDate('fulfilled_at',$date)->get();$refunds=Refund::query()->where('status','completed')->whereDate('processed_at',$date)->with(['sale:id,invoice_number','items.saleItem','approver:id,name'])->get();$grossProfit=$sales->sum(fn(Sale $s)=>$s->total-$s->items->sum(fn($i)=>$i->cost_price*$i->quantity));$digitalProfit=$digital->sum(fn(DigitalTransaction $d)=>$d->profit)+$topups->sum(fn(TopupOrder $t)=>$t->total_amount-$t->cost_price);$refundProfitReduction=$refunds->sum(fn(Refund $r)=>$r->amount-$r->items->where('restore_stock',true)->sum(fn($i)=>$i->saleItem->cost_price*$i->quantity));$grossRevenue=$sales->sum('total')+$digital->sum('selling_price')+$digital->sum('admin_fee')+$topups->sum('total_amount');$refundTotal=$refunds->sum('amount');$expenseTotal=$expenses->sum('amount');return response()->json(['data'=>['date'=>$date->toDateString(),'summary'=>['gross_revenue'=>(int)$grossRevenue,'refunds_total'=>(int)$refundTotal,'net_revenue'=>(int)$grossRevenue-(int)$refundTotal,'expenses_total'=>(int)$expenseTotal,'gross_profit'=>(int)$grossProfit+(int)$digitalProfit-(int)$refundProfitReduction,'net_cash'=>(int)$grossRevenue-(int)$refundTotal-(int)$expenseTotal,'completed_orders'=>ServiceOrder::query()->where('status','selesai')->whereDate('updated_at',$date)->count()],'sales'=>$sales->map(fn(Sale $s)=>['id'=>$s->id,'invoice_number'=>$s->invoice_number,'cashier'=>$s->user?->name,'total'=>$s->total,'completed_at'=>$s->completed_at?->toIso8601String()])->values(),'expenses'=>$expenses->map(fn(Expense $e)=>['expense_number'=>$e->expense_number,'category'=>$e->category?->name,'description'=>$e->description,'amount'=>$e->amount])->values(),'digital_transactions'=>$digital->map(fn(DigitalTransaction $d)=>['transaction_number'=>$d->transaction_number,'type'=>$d->type,'provider'=>$d->provider,'selling_price'=>$d->selling_price,'admin_fee'=>$d->admin_fee,'profit'=>$d->profit])->values(),'topups'=>$topups->map(fn(TopupOrder $t)=>['order_number'=>$t->order_number,'product_name'=>$t->product_name,'destination'=>$t->maskedDestination(),'source'=>str_starts_with((string)$t->source_reference,'whatsapp:')?'WhatsApp':'Web','total_amount'=>$t->total_amount,'profit'=>$t->total_amount-$t->cost_price,'fulfilled_at'=>$t->fulfilled_at?->toIso8601String()])->values(),'refunds'=>$refunds->map(fn(Refund $r)=>['refund_number'=>$r->refund_number,'invoice_number'=>$r->sale?->invoice_number,'approver'=>$r->approver?->name,'method'=>$r->method,'amount'=>$r->amount])->values()]]);}
public function __construct(private readonly RequestActionApproval $requestApproval){}private function authorizeFinance(Request $request):void{abort_unless($request->user()->isStaff()&&$request->user()->tokenCan('staff:finance')&&$request->user()->hasRole('owner','admin'),403);}}